#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    int T = 1;
    #pragma omp parallel
    {
        #pragma omp single
        { T = omp_get_num_threads(); }
    }
    if (T < 1) T = 1;

    std::vector<long long> blockSums(T + 1, 0LL); // blockSums[t] = sum of block t
    std::vector<long long> offsets(T + 1, 0LL);   // offsets[t] = sum of blocks after t

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int numThreads = omp_get_num_threads();

        const int start = (tid * n) / numThreads;
        const int end   = ((tid + 1) * n) / numThreads; // exclusive

        long long localSum = 0;
        for (int i = start; i < end; ++i) localSum += x[i];

        // Each thread writes a distinct element: safe
        blockSums[tid] = localSum;

        #pragma omp barrier

        // Compute offsets once: offsets[tid] = sum of blockSums for blocks > tid
        #pragma omp single
        {
            long long acc = 0;
            for (int t = numThreads - 1; t >= 0; --t) {
                offsets[t] = acc;
                acc += blockSums[t];
            }
        }

        #pragma omp barrier

        // Fill output for this block, right-to-left, using the offset
        long long running = offsets[tid];
        for (int i = end - 1; i >= start; --i) {
            running += x[i];
            output[i] = static_cast<int>(running);
        }
    }
}
